window.OVA_CONTENT={"slug":"seccion-04-fisiologia-vegetal-y-produccion","title":"Fisiología vegetal y producción","minutes":40,"summary":"Relaciona fotosíntesis, respiración, transpiración, crecimiento y estrés con disponibilidad y calidad de materias primas.","objective":"Interpretar cambios productivos a partir de procesos fisiológicos vegetales y evidencia de manejo.","stages":[{"eyebrow":"Energía","title":"1. Fotosíntesis y biomasa","reading":"La fotosíntesis utiliza energía luminosa para formar compuestos orgánicos a partir de dióxido de carbono y agua. La biomasa producida sostiene gran parte de las materias primas agrícolas.","application":"La radiación disponible importa, pero su efecto depende también de agua, nutrientes, temperatura y área foliar activa.","activity":{"type":"choice","question":"¿Qué resultado directo se asocia con la fotosíntesis?","options":["Formación de materia orgánica","Absorción intestinal","Producción de anticuerpos"],"answer":[0],"success":"La energía luminosa se incorpora en compuestos orgánicos."}},{"eyebrow":"Procesos integrados","title":"2. Respiración y transpiración","reading":"La respiración libera energía utilizable a partir de moléculas orgánicas. La transpiración contribuye al movimiento de agua y minerales y al balance térmico, aunque un exceso puede intensificar el déficit hídrico.","application":"Los procesos no deben evaluarse aislados: una planta mantiene intercambios coordinados con suelo y atmósfera.","activity":{"type":"match","question":"Relaciona proceso y función.","pairs":[{"label":"Respiración","value":"energia","option":"Liberar energía utilizable"},{"label":"Transpiración","value":"agua","option":"Favorecer flujo de agua y regulación térmica"},{"label":"Fotosíntesis","value":"biomasa","option":"Formar compuestos orgánicos"}],"answer":["energia","agua","biomasa"],"success":"Cada proceso aporta a la producción de manera diferente."}},{"eyebrow":"Crecimiento","title":"3. De los recursos al rendimiento","reading":"Raíces, tallos y hojas captan, transportan y transforman recursos. La división y expansión celular convierten esa disponibilidad en crecimiento, sujeto a regulación y límites ambientales.","application":"El rendimiento final acumula decisiones de manejo y respuestas fisiológicas a lo largo del ciclo.","activity":{"type":"order","question":"Ordena una cadena causal simplificada.","items":["Disponibilidad de recursos","Captación y transporte","Metabolismo y regulación","Crecimiento de órganos","Cantidad y calidad cosechada"],"answer":[0,1,2,3,4],"success":"El rendimiento emerge de una cadena de procesos."}},{"eyebrow":"Estrés","title":"4. Factores abióticos y bióticos","reading":"Temperatura extrema, salinidad o déficit de agua son factores abióticos; patógenos, plagas y competencia corresponden a interacciones bióticas. Ambos pueden reducir crecimiento y calidad.","application":"Identificar la categoría ayuda a elegir indicadores y medidas, pero varios estresores pueden actuar al mismo tiempo.","activity":{"type":"multi","question":"Selecciona factores abióticos.","options":["Déficit hídrico","Alta salinidad","Hongo patógeno","Temperatura elevada"],"answer":[0,1,3],"success":"Los factores abióticos no son organismos."}},{"eyebrow":"Caso aplicado","title":"5. Menos biomasa y menor firmeza","reading":"Un cultivo para transformación presenta menor biomasa y frutos menos firmes durante semanas de alta temperatura y riego irregular. También cambió la fertilización.","application":"La explicación debe integrar registros climáticos, agua, nutrición, estado fisiológico y evidencia sanitaria.","activity":{"type":"choice","question":"¿Qué acción ofrece mejor diagnóstico inicial?","options":["Comparar registros y medir variables antes de atribuir una causa","Aplicar cualquier insumo inmediatamente","Concluir que todo se debe a la variedad"],"answer":[0],"success":"Una decisión sólida comienza con evidencia integrada."}}],"number":"04","references":["Audesirk, T. et al. (2017). Biología: La vida en la tierra con fisiología. Pearson Educación.","Freeman, S. (2009). Biología. Pearson Educación.","Gutiérrez Ramírez, L. A. (2016). Los microorganismos en la agroindustria. Editorial Lasallista.","Mader, S. S. (2024). Biología. McGraw-Hill.","Velázquez Ocampo, M. P. (2020). Biología II. Cengage Learning."]};